import { cloneVNode, computed, defineComponent, h, type PropType } from 'vue';
import { buttonGroupStyleKeys, getButtonGroupStyleKeys } from '../lib/core';
import type { ButtonGroupOrientation } from '../lib/core';
import styles from './button-group.module.scss';

export const ButtonGroup = defineComponent({
	name: 'ButtonGroup',
	props: {
		orientation: {
			type: String as PropType<ButtonGroupOrientation>,
			default: 'horizontal',
		},
	},
	setup(props, { slots, attrs }) {
		const styleKeys = computed(() => getButtonGroupStyleKeys(props.orientation));
		const rootClass = computed(() => [styles[styleKeys.value.base], styles[styleKeys.value.orientation]]);

		return () =>
			h('div', { ...attrs, role: 'group', 'data-slot': 'button-group', 'data-orientation': props.orientation, class: [...rootClass.value, attrs.class] }, slots.default?.());
	},
});

export const ButtonGroupText = defineComponent({
	name: 'ButtonGroupText',
	props: {
		asChild: { type: Boolean, default: false },
	},
	setup(props, { slots, attrs }) {
		return () => {
			const children = slots.default?.();

			if (props.asChild) {
				const firstChild = Array.isArray(children) ? children[0] : children;

				if (firstChild) {
					const childProps = (firstChild.props ?? {}) as { class?: unknown };
					return cloneVNode(firstChild, {
						...attrs,
						'data-slot': 'button-group-text',
						class: [styles[buttonGroupStyleKeys.text], attrs.class, childProps.class].filter(Boolean),
					});
				}
			}

			return h('div', { ...attrs, 'data-slot': 'button-group-text', class: [styles[buttonGroupStyleKeys.text], attrs.class] }, children);
		};
	},
});

export const ButtonGroupSeparator = defineComponent({
	name: 'ButtonGroupSeparator',
	props: {
		orientation: {
			type: String as PropType<ButtonGroupOrientation>,
			default: 'vertical',
		},
	},
	setup(props, { attrs }) {
		return () =>
			h('div', {
				...attrs,
				role: 'none',
				'aria-hidden': 'true',
				'data-slot': 'button-group-separator',
				'data-orientation': props.orientation,
				class: [styles[buttonGroupStyleKeys.separator], attrs.class],
			});
	},
});

export default ButtonGroup;

@use '../../../styles/variables/colors' as *;

.buttonGroup {
	display: flex;
	width: fit-content;
	align-items: stretch;

	> * {
		&:focus-visible {
			position: relative;
			z-index: 1;
		}
	}

	// 嵌套按钮组
	[data-slot='button-group'] {
		gap: $spacing-2;
	}

	// 排列方向
	&.orientationHorizontal {
		flex-direction: row;

		// 直接子元素之间的连接样式
		> *:not(:first-child) {
			border-left: none;
			border-top-left-radius: 0;
			border-bottom-left-radius: 0;
		}

		> *:not(:last-child) {
			border-top-right-radius: 0;
			border-bottom-right-radius: 0;
		}
	}

	&.orientationVertical {
		flex-direction: column;

		> *:not(:first-child) {
			border-top: none;
			border-top-left-radius: 0;
			border-top-right-radius: 0;
		}

		> *:not(:last-child) {
			border-bottom-right-radius: 0;
			border-bottom-left-radius: 0;
		}
	}
}

.text {
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius;
	border: 1px solid $border;
	background-color: $muted;
	padding: 0 $spacing-4;
	font-size: $text-sm;
	font-weight: $font-medium;
	box-shadow: $shadow-sm;

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
	}
}

.separator {
	position: relative;
	align-self: stretch;
	margin: 0;
	background-color: $input;

	&[data-orientation='vertical'] {
		height: auto;
		width: 1px;
	}

	&[data-orientation='horizontal'] {
		height: 1px;
		width: auto;
	}
}
